import pako from 'pako';

const base64ToUint8Array = (base64: string): Uint8Array => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (const [index, char] of [...binary].entries()) {
    bytes[index] = char.codePointAt(0) ?? 0;
  }
  return bytes;
};

const uint8ArrayToBase64 = (bytes: Uint8Array): string => {
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCodePoint(byte);
  }
  return btoa(binary);
};

export const compressToBase64 = (input: string): string =>
  uint8ArrayToBase64(pako.gzip(input));

export const decompressFromBase64 = (base64: string): string =>
  pako.ungzip(base64ToUint8Array(base64), { to: 'string' });
